195:       uniforms: {
196:         topColor: { value: new THREE.Color(0x061017) },
197:         horizonColor: { value: new THREE.Color(0x3a4f39) },
198:         sunColor: { value: new THREE.Color(0x7e825e) },
199:       },
200:       vertexShader: `
201:         varying vec3 vWorld;
202:         void main() {
203:           vec4 world = modelMatrix * vec4(position, 1.0);
204:           vWorld = world.xyz;
205:           gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
206:         }
