208:       fragmentShader: `
209:         uniform vec3 topColor;
210:         uniform vec3 horizonColor;
211:         uniform vec3 sunColor;
212:         varying vec3 vWorld;
213:         void main() {
214:           vec3 dir = normalize(vWorld);
