217:           float glow = pow(max(0.0, dot(dir, normalize(vec3(-0.45, 0.3, -0.84)))), 18.0);
218:           col += sunColor * glow * 0.25;
219:           float dither = fract(sin(dot(gl_FragCoord.xy, vec2(12.9898, 78.233))) * 43758.5453);
