319:   bindTouch() {
320:     const joy = this.ui.el.joyZone;
321:     const knob = this.ui.el.joyKnob;
322:     const look = document.getElementById('look-zone');
323:     let joyId = null;
324:     let lookId = null;
325:     let lookX = 0;
326:     let lookY = 0;
327:     const maxR = 38;
328:     const setJoy = (event) => {
329:       const rect = joy.getBoundingClientRect();
330:       const cx = rect.left + rect.width / 2;
331:       const cy = rect.top + rect.height / 2;
332:       let dx = event.clientX - cx;
333:       let dy = event.clientY - cy;
334:       const d = Math.hypot(dx, dy);
335:       if (d > maxR) {
336:         dx = (dx / d) * maxR;
337:         dy = (dy / d) * maxR;
338:       }
339:       knob.style.transform = `translate(calc(-50% + ${dx}px), calc(-50% + ${dy}px))`;
340:       this.touchMove.x = dx / maxR;
341:       this.touchMove.y = dy / maxR;
342:       this.touchMove.active = true;
343:     };
344:     const resetJoy = () => {
345:       joyId = null;
346:       this.touchMove.x = 0;
347:       this.touchMove.y = 0;
348:       this.touchMove.active = false;
349:       knob.style.transform = 'translate(-50%, -50%)';
350:     };
351:     joy.addEventListener('pointerdown', (event) => {
352:       joyId = event.pointerId;
353:       joy.setPointerCapture(event.pointerId);
354:       setJoy(event);
355:     });
356:     joy.addEventListener('pointermove', (event) => {
357:       if (joyId === event.pointerId) setJoy(event);
358:     });
359:     joy.addEventListener('pointerup', resetJoy);
360:     joy.addEventListener('pointercancel', resetJoy);
361:     look.addEventListener('pointerdown', (event) => {
362:       lookId = event.pointerId;
363:       lookX = event.clientX;
364:       lookY = event.clientY;
365:       look.setPointerCapture(event.pointerId);
366:     });
367:     look.addEventListener('pointermove', (event) => {
368:       if (lookId !== event.pointerId) return;
369:       const dx = event.clientX - lookX;
370:       const dy = event.clientY - lookY;
371:       lookX = event.clientX;
372:       lookY = event.clientY;
373:       this.camYaw -= dx * 0.006;
374:       this.orbitPitch = clamp(this.orbitPitch + dy * 0.004, 0.02, 1.05);
375:     });
376:     look.addEventListener('pointerup', () => { lookId = null; });
377:     look.addEventListener('pointercancel', () => { lookId = null; });
378:     const sprintBtn = this.ui.el.btnSprint;
379:     sprintBtn.addEventListener('pointerdown', (event) => {
380:       event.preventDefault();
381:       this.touchSprint = true;
382:       sprintBtn.classList.add('on');
383:     });
384:     const stopSprint = () => {
385:       this.touchSprint = false;
386:       sprintBtn.classList.remove('on');
387:     };
388:     sprintBtn.addEventListener('pointerup', stopSprint);
389:     sprintBtn.addEventListener('pointercancel', stopSprint);
390:     this.ui.el.btnCrouch.addEventListener('click', () => this.toggleCrouch());
391:     this.ui.el.btnCamera.addEventListener('click', () => this.toggleCamera());
392:     this.ui.el.btnInteract.addEventListener('click', () => this.tryInteract());
393:     this.ui.el.btnLight.addEventListener('click', () => this.toggleFlashlight());
394:     this.ui.el.btnMap.addEventListener('click', () => {
395:       if (this.state === 'playing') this.openMap();
396:       else if (this.state === 'map') this.closeMap();
397:     });
398:     this.ui.el.btnPause.addEventListener('click', () => this.pause());
399:   }
