833:   updateCamera(dt, time) {
834:     if (this.state === 'dead') {
835:       const elapsed = Math.max(0, (performance.now() - this.deathTime) / 1000);
836:       const t = clamp(elapsed / this.deathDuration, 0, 1);
837:       const ease = t * t * (3 - 2 * t);
838:       const attackerSide = this.deathAttacker.clone().sub(this.deathFocus);
839:       attackerSide.y = 0;
840:       if (attackerSide.lengthSq() < 0.01) attackerSide.set(Math.sin(this.deathYaw), 0, Math.cos(this.deathYaw));
841:       attackerSide.normalize();
842:       const closeShot = this.deathFocus.clone().addScaledVector(attackerSide, 2.8 - ease * 0.7);
843:       closeShot.y += 1.15 - ease * 0.25;
844:       closeShot.x += Math.sin(elapsed * 1.4) * 0.035;
845:       this.camera.position.copy(this.deathCameraStart).lerp(closeShot, ease);
846:       const lookAt = this.deathFocus.clone().lerp(this.deathAttacker, Math.min(0.28, ease * 0.28));
847:       this.camera.lookAt(lookAt);
848:       return;
849:     }
850:     const isFirst = this.cameraMode === 'first';
851:     if (isFirst) {
852:       this.player.setHidden(true);
853:       this.fpArms.visible = true;
854:       const bobSpeed = this.player.speed;
855:       this.fpBob += dt * (1.4 + bobSpeed * 1.4);
856:       const bob = this.player.moving && this.player.onGround ? Math.sin(this.fpBob * 2.1) * 0.017 * clamp(bobSpeed / 4, 0, 1.4) : 0;
857:       this.camera.position.set(this.player.position.x, this.player.position.y + 1.62 + bob, this.player.position.z);
858:       const lookPitch = 0.22 - this.orbitPitch;
859:       _camDir.set(
860:         -Math.sin(this.camYaw) * Math.cos(lookPitch),
861:         Math.sin(lookPitch),
862:         -Math.cos(this.camYaw) * Math.cos(lookPitch),
863:       ).normalize();
864:       _target.copy(this.camera.position).addScaledVector(_camDir, 12);
865:       this.camera.lookAt(_target);
866:       this.fpArms.position.y = -0.28 + bob * 1.3;
867:       this.fpArms.rotation.z = Math.sin(this.fpBob * 1.05) * 0.008;
868:       this.camera.fov = damp(this.camera.fov, this.player.sprinting ? 69 : this.player.crouching ? 58 : 62, 6, dt);
869:       this.camera.updateProjectionMatrix();
870:       return;
871:     }
872:     this.player.setHidden(false);
873:     this.fpArms.visible = false;
874:     const crouchOffset = this.player.crouching ? -0.32 : 0;
875:     _target.set(this.player.position.x, this.player.position.y + 1.18 + crouchOffset, this.player.position.z);
876:     // Over-the-shoulder framing keeps the ape from masking the interaction
877:     // point and gives the lobby a more cinematic silhouette.
878:     _camRight.set(Math.cos(this.camYaw), 0, -Math.sin(this.camYaw));
879:     const portrait = this.camera.aspect < 0.8;
880:     const shoulder = this.player.inside ? (portrait ? 0.68 : 0.46) : (portrait ? 0.9 : 0.62);
881:     _target.addScaledVector(_camRight, shoulder);
882:     const distance = this.player.inside
883:       ? (portrait ? 3.55 : 3.05)
884:       : this.player.crouching ? 3.7 : (portrait ? 5.2 : 4.35);
885:     const cp = Math.cos(this.orbitPitch) * distance;
886:     _desiredCam.set(
887:       _target.x + Math.sin(this.camYaw) * cp,
888:       _target.y + Math.sin(this.orbitPitch) * distance,
889:       _target.z + Math.cos(this.camYaw) * cp,
890:     );
891:     // Camera collision: shorten the boom if the line crosses solid geometry.
892:     let maxT = 1;
893:     for (let t = 0.18; t <= 1; t += 0.075) {
894:       const sx = _target.x + (_desiredCam.x - _target.x) * t;
895:       const sz = _target.z + (_desiredCam.z - _target.z) * t;
896:       if (this.cameraBlockedAt(sx, sz)) {
897:         maxT = Math.max(0.16, t - 0.1);
898:         break;
899:       }
900:     }
901:     _desiredCam.lerpVectors(_target, _desiredCam, maxT);
902:     const minY = (this.player.inside ? 0.25 : this.player.position.y + 0.35);
903:     _desiredCam.y = Math.max(_desiredCam.y, minY);
904:     if (this.player.inside) _desiredCam.y = Math.min(_desiredCam.y, 4.15);
905:     const speed = this.snapCamera ? 200 : 12;
906:     this.camera.position.lerp(_desiredCam, 1 - Math.exp(-speed * dt));
907:     if (this.snapCamera) this.snapCamera = false;
908:     _look.copy(_target);
909:     // Subtle aim lead in the direction of travel.
910:     if (this.player.moving) {
911:       _look.x += Math.sin(this.player.visualYaw) * this.player.speed * 0.045;
912:       _look.z += Math.cos(this.player.visualYaw) * this.player.speed * 0.045;
913:     }
914:     this.shake.offset(_shake);
915:     this.camera.position.add(_shake);
916:     this.camera.lookAt(_look);
917:     this.camera.fov = damp(this.camera.fov, this.player.sprinting ? 66 : portrait ? 68 : 61, 4, dt);
918:     this.camera.updateProjectionMatrix();
919:   }
