921:   cameraBlockedAt(x, z) {
922:     for (const c of this.lab.colliders) {
923:       if (!c.active) continue;
924:       if (x > c.minX && x < c.maxX && z > c.minZ && z < c.maxZ) return true;
925:     }
926:     if (!this.lab.isInside(x, z, -0.4)) {
927:       for (const tree of this.jungle.treeColliders) {
928:         const dx = x - tree.x;
929:         const dz = z - tree.z;
930:         if (dx * dx + dz * dz < (tree.radius + 0.22) ** 2) return true;
931:       }
932:     }
933:     return false;
934:   }
