451:   buildMapTerrain(w, h) {
452:     const canvas = document.createElement('canvas');
453:     canvas.width = w;
454:     canvas.height = h;
455:     const ctx = canvas.getContext('2d');
456:     const cell = 8;
457:     for (let y = 0; y < h; y += cell) {
458:       for (let x = 0; x < w; x += cell) {
459:         const wx = ((x + cell / 2) / w - 0.5) * 500;
460:         const wz = ((y + cell / 2) / h - 0.5) * 500;
461:         const ht = terrainHeight(wx, wz);
462:         const v = clamp(0.16 + ht / 42, 0.04, 0.46);
463:         const moss = clamp(0.3 + ht / 55, 0.12, 0.56);
464:         ctx.fillStyle = `rgb(${Math.floor(12 + v * 40)}, ${Math.floor(25 + moss * 54)}, ${Math.floor(18 + v * 30)})`;
465:         ctx.fillRect(x, y, cell, cell);
466:         if (ht > 7 && (x + y) % 32 === 0) {
467:           ctx.fillStyle = 'rgba(137,159,104,0.1)';
468:           ctx.fillRect(x, y, cell, cell);
469:         }
470:       }
471:     }
472:     // Contour speckle.
473:     ctx.globalAlpha = 0.15;
474:     for (let i = 0; i < 250; i += 1) {
475:       ctx.fillStyle = i % 3 ? '#779057' : '#233f25';
476:       ctx.fillRect(Math.floor(Math.random() * w), Math.floor(Math.random() * h), 2, 2);
477:     }
478:     ctx.globalAlpha = 1;
479:     this.mapTerrain = canvas;
480:   }
