const targets = await fetch('http://127.0.0.1:9222/json').then((r) => r.json());
const target = targets.find((item) => item.type === 'page');
if (!target) throw new Error('No Chrome page target');
const ws = new WebSocket(target.webSocketDebuggerUrl);
let nextId = 0;
const pending = new Map();
ws.addEventListener('message', (event) => {
  const message = JSON.parse(event.data);
  if (message.id && pending.has(message.id)) {
    const { resolve, reject } = pending.get(message.id);
    pending.delete(message.id);
    if (message.error) reject(new Error(message.error.message));
    else resolve(message.result);
  }
});
await new Promise((resolve, reject) => {
  ws.addEventListener('open', resolve, { once: true });
  ws.addEventListener('error', reject, { once: true });
});
const send = (method, params = {}) => new Promise((resolve, reject) => {
  const id = ++nextId;
  pending.set(id, { resolve, reject });
  ws.send(JSON.stringify({ id, method, params }));
});
const evaluate = async (expression) => {
  const { result, exceptionDetails } = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (exceptionDetails) throw new Error(exceptionDetails.text);
  return result.value;
};
await send('Page.enable');
await send('Runtime.enable');
await send('Page.navigate', { url: 'http://127.0.0.1:3002' });
await new Promise((resolve) => setTimeout(resolve, 6000));
let ready = await evaluate('Boolean(window.__apeTest?.jungle && window.__apeTest?.lab)');
if (!ready) throw new Error('Game did not finish loading');
const outcome = await evaluate(`(() => {
  const game = window.__apeTest;
  const checks = {};
  document.getElementById('start-btn').click();
  checks.started = game.state === 'playing';
  game.onTerminal();
  checks.lockedBeforeCores = game.state === 'playing' && document.querySelector('#toast')?.textContent?.includes('UPLINK LOCKED');
  for (const core of game.jungle.cores) {
    core.collected = true;
    game.onCoreCollected(core);
  }
  checks.objectiveComplete = document.getElementById('objective-title').textContent.includes('3 / 3') && document.querySelector('.objective-panel').classList.contains('complete');
  checks.terminalUnlocked = game.lab.terminalScreen.material.map !== null;
  game.onTerminal();
  checks.won = game.state === 'won' && document.getElementById('win-overlay').classList.contains('show');
  document.getElementById('win-retry-btn').click();
  checks.restarted = game.state === 'playing' && !document.getElementById('win-overlay').classList.contains('show') && game.jungle.cores.every((core) => !core.collected);
  checks.objectiveReset = document.getElementById('objective-title').textContent.includes('0 / 3') && !document.querySelector('.objective-panel').classList.contains('complete');
  return checks;
})()`);
console.log(JSON.stringify(outcome, null, 2));
if (Object.values(outcome).some((passed) => !passed)) process.exitCode = 1;
ws.close();

