import { statSync } from 'node:fs';
import { writeFileSync } from 'node:fs';

const targets = await fetch('http://127.0.0.1:9222/json').then((r) => r.json());
const target = targets.find((item) => item.type === 'page');
if (!target) throw new Error('No Chrome page target');
const ws = new WebSocket(target.webSocketDebuggerUrl);
let nextId = 0;
const pending = new Map();
const exceptions = [];
ws.addEventListener('message', (event) => {
  const message = JSON.parse(event.data);
  if (message.method === 'Runtime.exceptionThrown') {
    exceptions.push(message.params.exceptionDetails.exception?.description || message.params.exceptionDetails.text);
  }
  if (message.id && pending.has(message.id)) {
    const { resolve, reject } = pending.get(message.id);
    pending.delete(message.id);
    if (message.error) reject(new Error(message.error.message));
    else resolve(message.result);
  }
});
await new Promise((resolve, reject) => {
  ws.addEventListener('open', resolve, { once: true });
  ws.addEventListener('error', reject, { once: true });
});
const send = (method, params = {}) => new Promise((resolve, reject) => {
  const id = ++nextId;
  pending.set(id, { resolve, reject });
  ws.send(JSON.stringify({ id, method, params }));
});
const evaluate = async (expression) => {
  const { result, exceptionDetails } = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (exceptionDetails) throw new Error(exceptionDetails.text);
  return result.value;
};
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const key = async (type, code, keyValue) => {
  await send('Input.dispatchKeyEvent', { type, code, key: keyValue, windowsVirtualKeyCode: keyValue.toUpperCase().charCodeAt(0) });
};

await send('Page.enable');
await send('Runtime.enable');
await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 720, deviceScaleFactor: 1, mobile: false });
await send('Page.navigate', { url: 'http://127.0.0.1:3002' });
await sleep(7000);
const loaded = await evaluate(`Boolean(window.__APE_PROJECT__?.jungle)`);
await evaluate(`document.getElementById('start-btn').click()`);
await sleep(1300);
const before = await evaluate(`(() => {
  const game = window.__APE_PROJECT__;
  const p = game.player.position.clone();
  return {
    state: game.state,
    pos: [p.x, p.y, p.z],
    missionEls: Boolean(document.querySelector('.objective-panel') || document.getElementById('objective-title') || document.getElementById('win-overlay')),
    coreInteractables: game.jungle.cores.filter((core) => core.interactable).length,
    collectMethod: typeof game.jungle.collectCore,
    terminalInteractive: Boolean(game.lab.terminalInteractable),
    labInteractables: [...new Set(game.lab.interactables.map((item) => item.kind))],
    startBrief: document.querySelector('.start-brief p').textContent.replace(/\\s+/g, ' ').trim(),
    mapLegend: document.querySelector('.map-legend').textContent.replace(/\\s+/g, ' ').trim(),
  };
})()`);
await key('keyDown', 'KeyW', 'w');
await sleep(2200);
await key('keyUp', 'KeyW', 'w');
await sleep(400);
const moved = await evaluate(`(() => {
  const game = window.__APE_PROJECT__;
  const p = game.player.position.clone();
  return { pos: [p.x, p.y, p.z], zone: document.getElementById('zone-label').textContent };
})()`);
await key('keyDown', 'KeyM', 'm');
await key('keyUp', 'KeyM', 'm');
await sleep(800);
const map = await evaluate(`({
  open: document.getElementById('map-overlay').classList.contains('show'),
  legend: document.querySelector('.map-legend').textContent.replace(/\\s+/g, ' ').trim(),
  state: window.__APE_PROJECT__.state,
})`);
await key('keyDown', 'KeyM', 'm');
await key('keyUp', 'KeyM', 'm');
await sleep(700);
const screenshot = await send('Page.captureScreenshot', { format: 'jpeg', quality: 80, fromSurface: true });
writeFileSync('/tmp/opencode/ape-wander-final.jpg', Buffer.from(screenshot.data, 'base64'));
const shotSize = statSync('/tmp/opencode/ape-wander-final.jpg').size;
const dx = Math.abs(moved.pos[0] - before.pos[0]);
const dz = Math.abs(moved.pos[2] - before.pos[2]);
console.log(JSON.stringify({ loaded, before, moved, map, shotSize, exceptions }, null, 2));
const pass = loaded
  && before.state === 'playing'
  && !before.missionEls
  && before.coreInteractables === 0
  && before.collectMethod === 'undefined'
  && !before.terminalInteractive
  && before.labInteractables.every((kind) => kind === 'door')
  && before.startBrief.includes('No mission')
  && !before.mapLegend.includes('CORE')
  && map.open
  && map.state === 'playing'
  && !map.legend.includes('CORE')
